 237→	if err := cmd.Run(); err != nil {
 238→		t.Fatalf("failed to init git repo: %v", err)
 239→	}
 240→
 241→	// Relative core.hooksPath should resolve relative to repo root.
 242→	cmd = exec.CommandContext(ctx, "git", "config", "core.hooksPath", ".githooks")
 243→	cmd.Dir = tmpDir
 244→	if err := cmd.Run(); err != nil {
 245→		t.Fatalf("failed to set relative core.hooksPath: %v", err)
 246→	}
 247→	relativeResult, err := getHooksDirInPath(tmpDir)
 248→	if err != nil {
 249→		t.Fatalf("unexpected error for relative hooks path: %v", err)
 250→	}
 251→	relativeExpected := filepath.Join(tmpDir, ".githooks")
 252→	if filepath.Clean(relativeResult) != filepath.Clean(relativeExpected) {
 253→		t.Errorf("relative core.hooksPath expected %s, got %s", relativeExpected, relativeResult)
 254→	}
 255→
 256→	// Absolute core.hooksPath should be returned unchanged.
 257→	absHooksPath := filepath.Join(tmpDir, "abs-hooks")
 258→	cmd = exec.CommandContext(ctx, "git", "config", "core.hooksPath", absHooksPath)
