// to w if any are found. Returns the detected managers.
func CheckAndWarnHookManagers(w io.Writer) []hookManager {
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return nil
	}

	managers := detectHookManagers(repoRoot)
	if len(managers) == 0 {
		return nil
	}

	var cmdPrefix string
	if isLocalDev() {
		cmdPrefix = "go run ./cmd/entire/main.go"
	} else {
		cmdPrefix = "entire"
	}

	warning := hookManagerWarning(managers, cmdPrefix)
	if warning != "" {
		fmt.Fprintln(w)
		fmt.Fprint(w, warning)
	}

	return managers
}

